import java.util.Scanner;
import io.github.mrrefactoring.Fraction;

//The function is: AB^x

public class functions_eternity {


	public class Power {
	    public static void main(String[] args) {
	        Scanner sc = new Scanner(System.in);
	        System.out.print("Value of A: ");
	        double a = sc.nextDouble();
	        System.out.print("Value of B: ");
	        double b = sc.nextDouble();
	        System.out.print("Value of x: ");
	        double x = sc.nextDouble();
	        double result = power(a, b, x);
	        System.out.println(a + b + "^" + x + " = " + result);
	    }

	    public static double power(double a, double b, double x) {
	    	
	    	if (a == 0) {
	    		return 0;
	    	}
	    	
	    	if (b == 0) {
		        if (x > 0) {
		        	return 0;
		        }
		        else if (x == 0) {
		        	return 1;
		        }
		        else {
		        	return Double.POSITIVE_INFINITY;
		        }
		        
	    	}
	       
	    	if (x == 0) {
	            return 1;
	        }
	      
	        double result = 1;
	        double absX = x;  
	        
	        String numString = String.valueOf(x);
	        int indexOfDecimal = numString.indexOf(".");
	         double decimal =  Double.parseDouble(numString.substring(indexOfDecimal));
	         System.out.println("DEBUG: decimal part " + decimal);
	         
	         
	         if (decimal != 0.0)
	         {
	             try {
	                 Fraction frac = new Fraction(b);
	                 System.out.println("DEBUG: fraction " + frac.toFraction());
	                 System.out.println("DEBUG: power with fraction " + frac.pow(decimal)); 
	                 result *= frac.pow(decimal).toDecimal();
	             } catch (Exception e) {
	                 System.out.println("ERROR - DIVISION BY ZERO");
	                 System.exit(0);
	             }

	         }
	       
	         
	        if (x < 0) {
	        	absX = -x;
	        }
	        
	        for (int i = 0; i < absX; i++) {
	            result *= b;
	        }
	        
	        if (x < 0) {
	        	result = 1 / result;
	        }
	        result *= a;
	        return result;
	    }
	}

}

